.telemetry{position: absolute; z-index: 5; width: clamp(220px, 18vw, 320px); padding: 14px 16px; border-radius: 3px; border: 1px solid rgba(255, 195, 126, 0.28); background: rgba(20, 20, 20, 0.42); backdrop-filter: blur(20px); box-shadow: rgba(0, 0, 0, 0.24) 0px 18px 48px;}
