.telemetry .d{margin-top: 8px; color: rgba(255, 255, 255, 0.72); line-height: 1.7; font-size: 12px;}
.hero-core{grid-column: 3 / span 8; align-self: center; position: relative; z-index: 3; padding: 22px; border-radius: 2.4rem; background: linear-gradient(rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02)), linear-gradient(135deg, rgba(255, 193, 127, 0.06), transparent 42%); box-shadow: rgba(0, 0, 0, 0.36) 0px 30px 90px;}
.core-shell{position: relative; overflow: hidden; border-radius: 2rem; border: 1px solid rgba(255, 199, 137, 0.2); background: rgba(20, 20, 20, 0.55); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(255, 255, 255, 0.03) 0px 0px 0px 1px;}
