.technical-footer::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at 20% 12%, rgba(255, 197, 112, 0.12), transparent 16%), linear-gradient(transparent 0px, transparent 66%, rgba(255, 255, 255, 0.03) 100%); pointer-events: none;}
.footer-shell{position: relative; z-index: 2; width: min(1680px, 100% - 28px); margin: 0px auto; display: grid; grid-template-columns: 1.15fr 0.85fr; gap: 18px;}
.footer-card{border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.03); box-shadow: rgba(0, 0, 0, 0.24) 0px 20px 70px; padding: 24px;}
.footer-card h2{font-size: clamp(3rem, 6vw, 6rem); line-height: 0.9; letter-spacing: -0.08em;}
.footer-card p{margin-top: 16px; color: rgba(255, 255, 255, 0.68); line-height: 1.95; max-width: 740px;}
.map-grid{display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 14px;}
.map{padding: 18px; border: 1px solid rgba(255, 255, 255, 0.08); background: linear-gradient(rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.016)), linear-gradient(135deg, rgba(255, 200, 120, 0.08), transparent 42%); min-height: 260px; overflow: hidden; position: relative;}
.map::before{content: ""; position: absolute; inset: 0px; background: repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.05) 0px, rgba(255, 255, 255, 0.05) 1px, transparent 1px, transparent 34px), repeating-linear-gradient(rgba(255, 255, 255, 0.05) 0px, rgba(255, 255, 255, 0.05) 1px, transparent 1px, transparent 28px); opacity: 0.12; pointer-events: none;}
.badges{display: grid; gap: 14px;}
.badge{min-height: 76px; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 18px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.04); text-transform: uppercase; letter-spacing: 0.22em; font-size: 10px; color: rgba(255, 255, 255, 0.72);}
.footer-links{margin-top: 18px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px;}
.footer-links a{display: flex; justify-content: space-between; align-items: center; padding: 14px 15px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.03); text-decoration: none; color: rgba(255, 255, 255, 0.8); font-family: "IBM Plex Mono", monospace; text-transform: uppercase; letter-spacing: 0.2em; font-size: 10px; transition: 0.25s;}
.footer-links a:hover{background: rgba(255, 255, 255, 0.06); color: rgb(255, 255, 255);}
.footer-line{margin-top: 18px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);}
.footer-bottom{margin-top: 18px; display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; color: rgba(255, 255, 255, 0.52); font-size: 12px; text-transform: uppercase; letter-spacing: 0.22em;}
.reveal{opacity: 0; transform: translateY(24px); transition: opacity 0.8s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);}
@media (max-width: 1180px){.footer-shell{grid-template-columns: 1fr;}}
@media (max-width: 1180px){.footer-shell{grid-template-columns: 1fr;}}
@media (max-width: 1180px){.footer-links, .map-grid{grid-template-columns: 1fr;}}
@media (max-width: 760px){.footer-shell{width: min(100% - 18px, 1680px);}}
@media (max-width: 760px){.footer-bottom{gap: 10px;}}
h2{font-size: inherit; font-weight: inherit;}
a{color: inherit; text-decoration: inherit;}
h2, p{margin: 0px;}
svg{display: block; vertical-align: middle;}
.absolute{position: absolute;}
.relative{position: relative;}
.inset-0{inset: 0px;}
.mt-4{margin-top: 1rem;}
.mt-5{margin-top: 1.25rem;}
.h-\[190px\]{height: 190px;}
.h-full{height: 100%;}
.w-full{width: 100%;}
.overflow-hidden{overflow: hidden;}
.rounded-\[2px\]{border-radius: 2px;}
.border{border-width: 1px;}
.text-\[10px\]{font-size: 10px;}
.uppercase{text-transform: uppercase;}
.tracking-\[0\.34em\]{letter-spacing: 0.34em;}
